using System.Text;
using System.Text.Json;
using EventContracts;
using Microsoft.AspNetCore.SignalR;
using Microsoft.EntityFrameworkCore;
using RabbitMQ.Client;
using RabbitMQ.Client.Events;

public sealed class Worker(IServiceScopeFactory scopes,IHubContext<DashboardHub> hub,IConfiguration config,ILogger<Worker> log):BackgroundService{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){while(!stoppingToken.IsCancellationRequested){try{using(var init=scopes.CreateScope()){await init.ServiceProvider.GetRequiredService<DashboardDb>().Database.MigrateAsync(stoppingToken);}var factory=new ConnectionFactory{Uri=new Uri(config["RabbitMq:Uri"]??Environment.GetEnvironmentVariable("RABBITMQ_URI")??"amqp://guest:guest@localhost:5672/")};await using var connection=await factory.CreateConnectionAsync(stoppingToken);await using var channel=await connection.CreateChannelAsync(cancellationToken:stoppingToken);await channel.ExchangeDeclareAsync("event.topic",ExchangeType.Topic,durable:true,autoDelete:false,cancellationToken:stoppingToken);await channel.QueueDeclareAsync("dashboard.events",true,false,false,cancellationToken:stoppingToken);foreach(var key in new[]{"event.participant.registered","event.participant.cancelled","event.participant.checkedin","event.event.created","event.event.updated","event.event.deleted"})await channel.QueueBindAsync("dashboard.events","event.topic",key,cancellationToken:stoppingToken);await channel.BasicQosAsync(0,1,false,stoppingToken);var consumer=new AsyncEventingBasicConsumer(channel);consumer.ReceivedAsync+=async(_,ea)=>{var acknowledged=false;try{var evt=JsonSerializer.Deserialize<BusinessEvent>(Encoding.UTF8.GetString(ea.Body.Span))??throw new InvalidDataException("Invalid event payload");using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<DashboardDb>();if(await db.Processed.AnyAsync(x=>x.EventId==evt.EventId,stoppingToken)){await channel.BasicAckAsync(ea.DeliveryTag,false,stoppingToken);acknowledged=true;return;}var data=evt.EventData;var row=await db.Events.IgnoreQueryFilters().SingleOrDefaultAsync(x=>x.EventId==data.EventEntityId,stoppingToken);if(row is null){row=new DashboardEvent{EventId=data.EventEntityId,EventName=data.EventName??"",Capacity=data.Capacity,UpdatedAt=evt.OccurredAt};db.Events.Add(row);}if(evt.EventVersion>=row.Version){row.EventName=data.EventName??row.EventName;row.Capacity=data.Capacity;row.Registered=data.RegisteredCount;row.CheckedIn=data.CheckedInCount;row.Version=evt.EventVersion;row.UpdatedAt=evt.OccurredAt;row.IsDeleted=evt.EventType=="EventDeleted";}if(evt.EventType=="ParticipantCancelled")row.Cancelled++;if(data.RegistrationId.HasValue&&data.ParticipantId.HasValue){var registration=await db.Registrations.FindAsync([data.RegistrationId.Value],stoppingToken);var status=evt.EventType=="ParticipantCancelled"?"Cancelled":evt.EventType=="ParticipantCheckedIn"?"CheckedIn":"Registered";if(registration is null){registration=new DashboardRegistration{RegistrationId=data.RegistrationId.Value,ParticipantId=data.ParticipantId.Value,Status=status,Version=evt.EventVersion};db.Registrations.Add(registration);}else if(evt.EventVersion>=registration.Version){registration.Status=status;registration.Version=evt.EventVersion;}}db.Activities.Add(new DashboardActivity{MessageId=evt.EventId,EventId=data.EventEntityId,EventType=evt.EventType,EventName=data.EventName??"",RegistrationCode=data.RegistrationCode??"",ParticipantName=data.ParticipantName,ParticipantId=data.ParticipantId,OccurredAt=evt.OccurredAt,CorrelationId=evt.CorrelationId});db.Processed.Add(new DashboardProcessed{EventId=evt.EventId,ProcessedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync(stoppingToken);await channel.BasicAckAsync(ea.DeliveryTag,false,stoppingToken);acknowledged=true;try{await hub.Clients.All.SendAsync("DashboardUpdated",new{eventId=data.EventEntityId,eventName=data.EventName,registered=row.Registered,checkedIn=row.CheckedIn,cancelled=row.Cancelled,capacity=row.Capacity},stoppingToken);var signal=evt.EventType switch{"ParticipantRegistered"=>"RegistrationCreated","ParticipantCancelled"=>"RegistrationCancelled","ParticipantCheckedIn"=>"ParticipantCheckedIn",_=>null};if(signal is not null)await hub.Clients.All.SendAsync(signal,new{eventId=data.EventEntityId,registrationCode=data.RegistrationCode,participantName=data.ParticipantName,occurredAt=evt.OccurredAt},stoppingToken);await hub.Clients.All.SendAsync("RecentActivityCreated",new{eventId=data.EventEntityId,eventName=data.EventName,type=evt.EventType,occurredAt=evt.OccurredAt},stoppingToken);}catch(Exception signalError){log.LogError(signalError,"Dashboard projection persisted but SignalR notification failed for {EventId}",evt.EventId);}log.LogInformation("Projected {EventType} {EventId} correlation {CorrelationId}",evt.EventType,evt.EventId,evt.CorrelationId);}catch(OperationCanceledException)when(stoppingToken.IsCancellationRequested){throw;}catch(Exception ex){if(acknowledged)log.LogError(ex,"Dashboard event {EventId} was acknowledged; post-processing failed",ea.BasicProperties.MessageId);else{log.LogError(ex,"Dashboard consumer failed; message will be retried");await channel.BasicNackAsync(ea.DeliveryTag,false,true,stoppingToken);}}};await channel.BasicConsumeAsync("dashboard.events",false,consumer,stoppingToken);await Task.Delay(Timeout.Infinite,stoppingToken);}catch(OperationCanceledException)when(stoppingToken.IsCancellationRequested){break;}catch(Exception ex){log.LogError(ex,"Dashboard RabbitMQ connection lost; reconnecting");await Task.Delay(TimeSpan.FromSeconds(3),stoppingToken);}}}
}
